{
  "application": "data-visualization",
  "case_id": "case-climate-energy-transition-dual-timeline",
  "language": "en",
  "style": {
    "theme": "editorial",
    "audience": "researchers and policy makers",
    "tone": "authoritative, data-dense, publication-ready"
  },
  "goal": [
    {
      "id": "dual-track-narrative",
      "insight": "Present two parallel timelines — fossil energy retirement events on one track and clean energy milestones on the other — so the viewer can visually trace the acceleration of both tracks converging toward an energy transition"
    },
    {
      "id": "encoding-mapping",
      "insight": "Encode each event as a marker on a horizontal timeline axis (x=year), with vertical position separating fossil (below) from clean (above), marker size mapped to event significance score, marker color mapped to energy sub-type (coal/oil/gas vs solar/wind/hydrogen), and an overlaid area or line showing global electricity generation share by clean energy"
    },
    {
      "id": "crossover-inflection",
      "insight": "Visually highlight the period around 2015–2025 where clean energy milestones densify and fossil retirement events accelerate, making the inflection zone prominent"
    },
    {
      "id": "generation-share-overlay",
      "insight": "Show the rising clean energy generation share as a continuous overlay so viewers can connect discrete milestone events to the aggregate shift in electricity mix"
    },
    {
      "id": "sub-type-differentiation",
      "insight": "Ensure coal, oil, gas, solar, wind, and hydrogen events are visually distinguishable by color so viewers can identify which sub-sectors lead the transition on each track"
    }
  ]
}

